        />
        <Button
          type="button"
          variant="ghost"
          size="icon-sm"
          aria-label={
            shown
              ? `Hide ${label.toLowerCase()}`
              : `Show ${label.toLowerCase()}`
          }
          aria-pressed={shown}
          onClick={() => setShown((was) => !was)}
          className="text-muted-foreground hover:text-foreground size-8"
        >
