const CodesStep = ({
  codes,
  id,
  onSaved,
  product,
  saved,
}: {
  codes: string[];
  id: string;
  onSaved: (saved: boolean) => void;
  product: string;
  saved: boolean;
}) => (
  <div className="flex flex-col gap-4">
