        id: "security",
        label: "Security",
      },
      {
        href: "#notifications",
        icon: Notification03Icon,
        id: "notifications",
        label: "Notifications",
      },
      {
        href: "#preferences",
        icon: SlidersHorizontalIcon,
        id: "preferences",
        label: "Preferences",
      },
